  echo "  9) Hermes       (~/.hermes/skills/devops/)"
  echo " 10) 全部安装"
  read -rp "请输入编号 [1-10]: " CHOICE
  case "$CHOICE" in
    1) TARGET="codex"       ;;
    2) TARGET="cursor"      ;;
    3) TARGET="claude"      ;;
    4) TARGET="gemini"      ;;
    5) TARGET="antigravity" ;;
    6) TARGET="copilot"     ;;
    7) TARGET="openclaw"    ;;
    8) TARGET="agents"      ;;
    9) TARGET="hermes"      ;;
   10) TARGET="all"         ;;
