    BACKUP_ROOT="${BASE_DIR}/.backups"
    mkdir -p "$BACKUP_ROOT"
    BACKUP="${BACKUP_ROOT}/${SKILL_NAME}-$(date +%Y%m%d-%H%M%S)-$$"
    [[ ! -e "$BACKUP" && ! -L "$BACKUP" ]] || { echo "Backup path already exists" >&2; exit 1; }
    mv "$DEST" "$BACKUP"
    echo "  ↪ 原版本已备份：$BACKUP"
